    Add(4,NoShape,12,L.IndexBuffer.GetNumIndices()/3,0,L.IndexBuffer.GetIndexDataSize()/L.IndexBuffer.GetNumIndices(),0,[&L](FWriter& W){const auto V=L.IndexBuffer.GetArrayView();for(int32 I=0;I<V.Num();++I)W.U32(V[I]);});
