        Add(11,Shape,4,E.GetNumTriangles(),0,4,1,[Object](FWriter& W){for(int32 I=0;I<Object->Elements().GetNumTriangles();++I)W.I32(Object->GetExternalFaceIndexFromInternal(I));});
