        Add(12,Shape,4,E.GetNumTriangles(),0,sizeof(decltype(Object->GetMaterialIndex(0u))),0,[Object](FWriter& W){for(int32 I=0;I<Object->Elements().GetNumTriangles();++I)W.U32(Object->GetMaterialIndex(uint32(I)));});
