        for(const auto& E:S.Entries){for(uint32 X:{E.Kind,E.Shape,E.Stride,E.N})W.U32(X);W.U64(E.Offset);W.U64(E.Bytes);for(uint32 X:{E.PositionBytes,E.IndexBytes,E.Flags,0u})W.U32(X);W.U64(0);W.U64(0);}
