FString ULivingTownContextCollisionInspection::ExportContextCollisionMeshes(const TArray<FString>& Paths,const FString& Relative)
{
    FString Receipt,Error;
    if(ExportContextCollisionMeshesImpl(Paths,Relative,Receipt,Error))return Receipt;
    return ContextIntake::Reply(Error.StartsWith(TEXT("HOLD_"))?TEXT("HOLD_RESOURCE_PENDING"):TEXT("REFUSED"),Error);
}
